import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Sesion } from '../../sesiones/entities/sesion.entity';
import { Instructor } from '../../instructores/entities/instructor.entity';

@Injectable()
export class AsignarInstructorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Sesion) private readonly sesiones: Repository<Sesion>,
    @InjectRepository(Instructor) private readonly instructores: Repository<Instructor>
  ) {}

  buscarSesionRepository(sesionId: number) {
    return this.sesiones.findOneBy({ id: sesionId });
  }

  buscarInstructorRepository(instructorId: number) {
    return this.instructores.findOneBy({ id: instructorId });
  }

  async asignarInstructorRepository(sesionId: number, instructorId: number, rol: string) {
    const asignacion = { sesionId, instructorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarInstructorRepository } from './repository';

@Injectable()
export class AsignarInstructorService {
  constructor(private readonly repository: AsignarInstructorRepository) {}

  async asignarInstructorService(sesionId: number, instructorId: number, rol: string) {
    const sesion = await this.repository.buscarSesionRepository(sesionId);
    const instructor = await this.repository.buscarInstructorRepository(instructorId);
    if (!sesion || !instructor) {
      throw new NotFoundException('No existe la sesion o el instructor');
    }

    try {
      return await this.repository.asignarInstructorRepository(sesionId, instructorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El instructor ya está asignado a esa sesion');
      }
      throw error;
    }
  }
}

import { Body, Controller, Param, Post } from '@nestjs/common';
import { AsignarInstructorService } from './service';

@Controller('sesiones/:sesionId/asignaciones')
export class AsignarInstructorController {
  constructor(private readonly service: AsignarInstructorService) {}

  @Post()
  asignar(@Param('sesionId') sesionId: string, @Body() datos: { instructorId: number; rol: string }) {
    return this.service.asignarInstructorService(Number(sesionId), datos.instructorId, datos.rol);
  }
}
